def retry_on_error(func, retries=3):
    for i in range(retries):
        try:
            return func()
        except Exception:
            if i == retries - 1:
                raise
    return None

print('Retry pattern')

import io

class CountingWriter(io.TextIOWrapper):
    def __init__(self, buffer):
        super().__init__(buffer)
        self.bytes_written = 0
    def write(self, s):
        result = super().write(s)
        self.bytes_written += len(s)
        return result

print('Custom writer')

